<script setup>
import { Head, Link, router, usePage } from '@inertiajs/vue3';
import { computed, ref } from 'vue';
import AdminLayout from '../../../layouts/AdminLayout.vue';
const props = defineProps({ kind: String, resources: Object, search: String, group: String, moduleGroups: Array });
const query = ref(props.search);
const rows = computed(() => props.kind === 'materials' ? [...props.resources.data].sort((a, b) => (a.group || 'Belum dikelompokkan').localeCompare(b.group || 'Belum dikelompokkan') || a.title.localeCompare(b.title)) : props.resources.data);
const title = computed(() => ({ frameworks: 'Acuan Pembelajaran', materials: 'Modul', assessments: 'Ujian' }[props.kind]));
const description = computed(() => ({ frameworks: 'Dasar penyusunan modul, misalnya HSK 1–HSK 2.', materials: 'Kelola modul pengajaran beserta cakupan HSK, BCT, dan bahan referensinya.', assessments: 'Buat soal untuk akhir paket atau level.' }[props.kind]));
</script>
<template>
    <Head :title="title" /><AdminLayout>
        <div class="learning-intro mb-6 flex flex-wrap items-center justify-between gap-5 rounded-2xl border border-line p-6"><div><h1 class="mt-2 text-2xl font-semibold text-brand">{{ title }}</h1><p class="mt-2 text-sm leading-6 text-muted">{{ description }}</p></div><div class="flex flex-wrap gap-3"><Link v-if="kind === 'materials'" href="/admin/learning/materials/coverage" class="admin-secondary">Kelola cakupan</Link><Link :href="`/admin/learning/${kind}/create`" class="admin-button">Tambah {{ kind === 'frameworks' ? 'acuan' : kind === 'materials' ? 'modul' : 'ujian' }}</Link></div></div>
        <Link v-if="kind === 'materials' && group" href="/admin/learning/materials" class="mb-5 inline-block text-sm font-semibold text-interactive">Tampilkan semua modul</Link><p v-if="usePage().props.flash?.success" role="status" class="mb-5 rounded-xl bg-brand-soft p-4 text-sm text-brand">{{ usePage().props.flash.success }}</p>
        <section class="learning-panel"><form class="flex flex-wrap gap-3 border-b border-line p-5" @submit.prevent="router.get(`/admin/learning/${kind}`, { search: query }, { preserveState: true })"><input v-model="query" type="search" aria-label="Cari judul" placeholder="Cari judul…" class="admin-input max-w-md" /><button class="admin-secondary">Cari</button></form><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-brand-soft/60 text-xs text-muted"><tr><th class="px-5 py-4">Judul</th><th v-if="kind === 'materials'" class="px-5 py-4">Cakupan</th><th v-if="kind === 'materials'" class="px-5 py-4">Bahan</th><th v-if="kind === 'assessments'" class="px-5 py-4">Tujuan ujian</th><th class="px-5 py-4">Status</th><th v-if="kind !== 'materials'" class="px-5 py-4">Versi</th><th class="px-5 py-4">Tindakan</th></tr></thead><tbody class="divide-y divide-line"><tr v-for="item in rows" :key="item.id"><td class="px-5 py-5"><p class="font-semibold text-brand">{{ item.title }}</p></td><td v-if="kind === 'materials'" class="px-5 py-5 text-xs">{{ item.reference_labels?.join('; ') || 'Belum diisi' }}</td><td v-if="kind === 'materials'" class="px-5 py-5 text-xs">{{ item.attachments_count }}</td><td v-if="kind === 'assessments'" class="px-5 py-5 text-xs"><template v-if="item.target">{{ item.target.program_name }} · {{ item.target.subprogram_name }}<br />{{ item.target.level_name }}<br />{{ item.target.package_name || 'Akhir level' }} · sesi {{ item.target.session_start }}–{{ item.target.session_end }}</template><span v-else>Belum ditentukan</span></td><td class="px-5 py-5"><span :class="['rounded-full px-3 py-1 text-xs', item.status === 'ready' ? 'bg-brand-soft text-brand' : 'bg-accent-soft text-ink']">{{ item.status === 'ready' ? 'Siap dipakai' : 'Draf' }}</span></td><td v-if="kind !== 'materials'" class="px-5 py-5 text-muted">v{{ item.revision }}</td><td class="px-5 py-5"><Link :href="`/admin/learning/${kind}/${item.id}/edit`" class="font-semibold text-interactive">Ubah</Link></td></tr><tr v-if="!resources.data.length"><td :colspan="kind === 'materials' ? 5 : kind === 'assessments' ? 5 : 4" class="px-5 py-14 text-center text-muted">{{ search ? 'Tidak ada hasil yang sesuai.' : 'Belum ada data. Mulai dengan menambahkan yang pertama.' }}</td></tr></tbody></table></div><nav v-if="resources.last_page > 1" aria-label="Halaman data" class="flex flex-wrap gap-2 border-t border-line p-5"><template v-for="(link, i) in resources.links" :key="i"><Link v-if="link.url" :href="link.url" class="admin-secondary" :aria-current="link.active ? 'page' : undefined"><span v-html="link.label" /></Link></template></nav></section>
        <p v-if="kind !== 'materials'" class="mt-5 text-xs leading-6 text-muted">Versi siap dipakai dapat dipilih pada kurikulum program. {{ kind === 'assessments' ? 'Penugasan dan pengerjaan siswa tersedia pada tahap LMS siswa berikutnya.' : 'Mengubah data membuat versi baru; versi terdahulu tetap tersimpan.' }}</p>
    </AdminLayout>
</template>
